        // RIGHT WAY: EC2 assumes a Role → temporary credentials.
        TemporaryCredentials creds = sts.assumeRole(
                "arn:aws:iam::111122223333:role/SettlementReaderRole",
                "ec2-settlement-session", Duration.ofHours(1));
        log.info(() -> "Assumed Role, token expires at " + creds.expiry());

        SettlementReader reader = new SettlementReader(creds);
        log.info(() -> "Read settlement file: " + reader.read("SETL-2026-10-29.csv"));

        // Cross-account: analytics assumes a production Role.
        TemporaryCredentials xacct = sts.assumeRole(
                "arn:aws:iam::999988887777:role/ProdSettlementReadRole",
                "analytics-session", Duration.ofMinutes(30));
        log.info(() -> "Cross-account token expires at " + xacct.expiry());

        // WRONG WAY illustrated — never do this:
        log.warning("Embedding an access key in code (AKIA...) would never expire and leak forever");
    }
}

// ─── Would be in TemporaryCredentials.java ───
class TemporaryCredentials {
    private final String accessKeyId, secretKey, sessionToken;
    private final Instant expiry;
    TemporaryCredentials(String id, String secret, String token, Instant expiry) {
        this.accessKeyId = id; this.secretKey = secret; this.sessionToken = token; this.expiry = expiry;
    }
    Instant expiry() { return expiry; }
    boolean expired() { return Instant.now().isAfter(expiry); }
    String sessionToken() { return sessionToken; }
}

// ─── Would be in AssumeRoleService.java ───
class AssumeRoleService {
    // Simulates STS AssumeRole: issues short-lived credentials.
    TemporaryCredentials assumeRole(String roleArn, String sessionName, Duration ttl) {
        String token = "STS-" + sessionName + "-" + System.nanoTime();
        return new TemporaryCredentials("ASIA-temp", "temp-secret", token, Instant.now().plus(ttl));
    }
}

// ─── Would be in SettlementReader.java ───
class SettlementReader {
    private final TemporaryCredentials creds;
    SettlementReader(TemporaryCredentials creds) { this.creds = creds; }
    String read(String key) {
        if (creds.expired()) throw new IllegalStateException("Credentials expired — refresh via STS");
        return "contents-of-" + key;  // would be an S3 GetObject call
    }
}

