        log.info(() -> "Can GetObject?  " + engine.evaluate(policy, "s3:GetObject",    "arn:aws:s3:::nbi-statements/stmt1.pdf"));
        log.warning(() -> "Can DeleteObject? " + engine.evaluate(policy, "s3:DeleteObject", "arn:aws:s3:::nbi-statements/stmt1.pdf"));
        log.warning(() -> "Can access other bucket? " + engine.evaluate(policy, "s3:GetObject", "arn:aws:s3:::other-bucket/x"));
