package com.bank.net;

import java.util.*;
import java.util.logging.*;

public class FirewallDemo {
    private static final Logger log = Logger.getLogger("Firewall");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Security Group: stateful, allow-only.
        SecurityGroup sg = new SecurityGroup();
        sg.allowInbound(8080, "10.0.0.0/16");   // from load balancer subnet
        sg.allowInbound(22,   "10.0.0.0/16");   // SSH from corporate

        log.info(() -> "SG inbound 8080 from 10.0.1.5 allowed: " + sg.inboundAllowed(8080, "10.0.1.5"));
        log.info(() -> "SG return traffic auto-allowed (stateful): " + sg.returnAllowed());
        log.warning(() -> "SG inbound 8080 from internet 203.0.113.9 allowed: " + sg.inboundAllowed(8080, "203.0.113.9"));

        // NACL: stateless, numbered allow + deny.
        NetworkAcl nacl = new NetworkAcl();
        nacl.addInbound(new AclRule(100, "allow", 8080, "10.0.0.0/16"));
        nacl.addInbound(new AclRule(200, "deny", 0, "203.0.113.0/24")); // block bad range
        log.info(() -> "NACL inbound 8080 from 10.0.1.5: " + nacl.evaluateInbound(8080, "10.0.1.5"));
        log.warning(() -> "NACL inbound from bad range 203.0.113.9: " + nacl.evaluateInbound(8080, "203.0.113.9"));
    }
}

// ─── Would be in SecurityGroup.java ───
class SecurityGroup {
    private final Map<Integer, String> inboundAllows = new HashMap<>();
    void allowInbound(int port, String cidr) { inboundAllows.put(port, cidr); }
    boolean inboundAllowed(int port, String sourceIp) {
        String cidr = inboundAllows.get(port);
        return cidr != null && sourceIp.startsWith(cidr.split("/")[0].substring(0, 4));
    }
    boolean returnAllowed() { return true; }  // stateful: responses always allowed
}

// ─── Would be in AclRule.java ───
class AclRule {
    final int number; final String action; final int port; final String cidr;
    AclRule(int number, String action, int port, String cidr) {
        this.number = number; this.action = action; this.port = port; this.cidr = cidr;
    }
    boolean matches(int p, String ip) {
        boolean portOk = port == 0 || port == p;
        boolean ipOk = ip.startsWith(cidr.split("/")[0].substring(0, 4));
        return portOk && ipOk;
    }
}

// ─── Would be in NetworkAcl.java ───
class NetworkAcl {
    private final List<AclRule> inbound = new ArrayList<>();
    void addInbound(AclRule r) {
        inbound.add(r);
        inbound.sort(Comparator.comparingInt(x -> x.number)); // lowest number first
    }
    String evaluateInbound(int port, String ip) {
        for (AclRule r : inbound) {                 // stop at first match
            if (r.matches(port, ip)) return r.action.toUpperCase();
        }
        return "DENY (implicit default)";
    }
}

