// ─── Would be in LoginEvent.java ───
class LoginEvent {
    final boolean success; final String user; final String sourceIp;
    LoginEvent(boolean success, String user, String sourceIp) {
        this.success = success; this.user = user; this.sourceIp = sourceIp;
    }
    @Override public String toString() {
        return (success ? "LOGIN OK " : "LOGIN FAIL ") + user + " from " + sourceIp;
    }
}

// ─── Would be in LoginAuditor.java ───
class LoginAuditor {
    List<LoginEvent> parse(List<String> lines) {
        List<LoginEvent> out = new ArrayList<>();
        for (String l : lines) {
            boolean ok = l.contains("Accepted");
            boolean fail = l.contains("Failed");
            if (!ok && !fail) continue;
            String user = extractAfter(l, ok ? "for " : "user ");
            String ip = extractAfter(l, "from ");
            out.add(new LoginEvent(ok, user, ip));
        }
        return out;
    }
    // Sources with failed attempts at or above the threshold look like brute force.
    Set<String> bruteForceSources(List<LoginEvent> events, int threshold) {
        Map<String, Integer> fails = new HashMap<>();
        for (LoginEvent e : events)
            if (!e.success) fails.merge(e.sourceIp, 1, Integer::sum);
        Set<String> bad = new HashSet<>();
        fails.forEach((ip, n) -> { if (n >= threshold) bad.add(ip); });
        return bad;
    }
    private String extractAfter(String line, String token) {
        int i = line.indexOf(token);
        if (i < 0) return "?";
        String rest = line.substring(i + token.length());
        return rest.split("\\s+")[0];
    }
}

// ─── Would be in LogInspector.java ───
class LogInspector {
    List<String> byLevel(List<String> lines, String level) {
        return lines.stream().filter(l -> l.startsWith(level)).toList();
    }
}

