class Route {
    final String cidr, target; final int prefix;
    Route(String cidr, String target) {
        this.cidr = cidr; this.target = target;
        this.prefix = Integer.parseInt(cidr.split("/")[1]);  // longer = more specific
    }
    boolean matches(String ip) {
        if (cidr.equals("0.0.0.0/0")) return true;
        String net = cidr.split("/")[0];
        int octets = prefix / 8;                              // simple octet compare for demo
        String[] a = net.split("\\."), b = ip.split("\\.");
        for (int i = 0; i < octets; i++) if (!a[i].equals(b[i])) return false;
        return true;
    }
}

// ─── Would be in RouteTable.java ───
class RouteTable {
    private final java.util.List<Route> routes = new java.util.ArrayList<>();
    void add(Route r) { routes.add(r); }
    // Longest-prefix match: most specific route wins.
    Route bestMatch(String ip) {
        Route best = null;
        for (Route r : routes)
            if (r.matches(ip) && (best == null || r.prefix > best.prefix)) best = r;
        return best;
    }
}

// ─── Would be in PacketRouter.java ───
class PacketRouter {
    private final RouteTable table;
    PacketRouter(RouteTable table) { this.table = table; }
    String route(String ip) {
        Route r = table.bestMatch(ip);
        return r == null ? "DROPPED (no route)" : r.target + " (via " + r.cidr + ")";
    }
}

