    public static void main(String[] args) {
        // Forward path all good, but the RETURN route is missing — classic failure.
        PathState s = new PathState();
        s.sourceRouteToTgw = true;
        s.sourceAttachmentAvailable = true;
        s.sourceAssociatedToTable = true;
        s.destRoutePropagated = true;
        s.destReturnRouteToTgw = false;     // <-- the real fault
        s.destSgAllows = true;
        s.naclBothWays = true;
        s.returnPropagated = false;          // <-- also missing

        TgwPathTracer tracer = new TgwPathTracer();
        log.warning(() -> "Diagnosis: " + tracer.trace(s));

        PathState ok = new PathState();
        ok.sourceRouteToTgw = ok.sourceAttachmentAvailable = ok.sourceAssociatedToTable = true;
        ok.destRoutePropagated = ok.destReturnRouteToTgw = ok.destSgAllows = true;
        ok.naclBothWays = ok.returnPropagated = true;
        log.info(() -> "Diagnosis: " + tracer.trace(ok));
    }
}

// ─── Would be in PathState.java ───
class PathState {
    boolean sourceRouteToTgw, sourceAttachmentAvailable, sourceAssociatedToTable;
    boolean destRoutePropagated, destReturnRouteToTgw, destSgAllows, naclBothWays;
    boolean returnPropagated;
}

// ─── Would be in TgwPathTracer.java ───
class TgwPathTracer {
    // Walk every hop in packet order, FORWARD then RETURN.
    String trace(PathState s) {
        if (!s.sourceRouteToTgw)          return "Source VPC subnet route table: add dest CIDR → TGW attachment";
        if (!s.sourceAttachmentAvailable) return "Source TGW attachment missing/not available";
        if (!s.sourceAssociatedToTable)   return "Source attachment not associated with any TGW route table";
        if (!s.destRoutePropagated)       return "Dest route NOT in source's TGW table — propagate or add static route";
        if (!s.destSgAllows)              return "Destination Security Group blocks inbound from source";
        if (!s.naclBothWays)              return "NACL must allow both directions on both subnets";
        // RETURN path — the step everyone forgets
        if (!s.destReturnRouteToTgw)      return "RETURN: dest VPC subnet route table missing source CIDR → TGW";
        if (!s.returnPropagated)          return "RETURN: source route not in dest's TGW table — reply has no path home";
        return "Path healthy both directions — communication works";
    }
}

