// ─── Would be in LifecyclePolicy.java ───
class LifecyclePolicy {
    private final List<TransitionRule> rules; // sorted by age ascending
    private final int expireAfterDays;

    LifecyclePolicy(List<TransitionRule> rules, int expireAfterDays) {
        this.rules = new ArrayList<>(rules);
        this.rules.sort(Comparator.comparingInt(TransitionRule::minAgeDays));
        this.expireAfterDays = expireAfterDays;
    }

    // The target class is the last rule whose age threshold the object has reached.
    String targetClass(S3Object o) {
        String cls = "STANDARD";
        for (TransitionRule r : rules) {
            if (o.ageDays() >= r.minAgeDays()) cls = r.storageClass();
        }
        return cls;
    }

    boolean shouldExpire(S3Object o) {
        return o.ageDays() >= expireAfterDays;
    }
}

