        String marker = bucket.delete("priya/aadhaar.pdf", 2);
        log.warning(() -> "Priya doc deleted, GET now hidden by delete marker " + marker);
        bucket.put("priya/aadhaar.pdf", "AADHAAR-DATA", 2); // ensure object exists first
        String m2 = bucket.delete("priya/aadhaar.pdf", 3);
        bucket.removeDeleteMarker("priya/aadhaar.pdf", m2);
        log.info(() -> "Restored Priya doc, current = " + bucket.getCurrent("priya/aadhaar.pdf"));

        // Lifecycle: expire noncurrent versions older than 90 days.
        int removed = bucket.expireNoncurrentOlderThan("rajesh/pan-card.pdf", 90, 200);
        log.info(() -> "Lifecycle expired " + removed + " old noncurrent version(s) to save cost");
    }
}

// ─── Would be in VersionedBucket.java ───
class VersionedBucket {
    private final String name;
    private final Map<String, List<ObjectVersion>> store = new HashMap<>();
    private int seq = 0;

    VersionedBucket(String name) { this.name = name; }

    String put(String key, String data, int dayCreated) {
        String versionId = "v" + (++seq);
        store.computeIfAbsent(key, k -> new ArrayList<>())
             .add(new ObjectVersion(versionId, data, false, dayCreated));
        return versionId;
    }

    // Delete writes a delete marker as the new current version (no data erased).
    String delete(String key, int day) {
        String markerId = "dm" + (++seq);
        store.computeIfAbsent(key, k -> new ArrayList<>())
             .add(new ObjectVersion(markerId, null, true, day));
        return markerId;
    }

    void removeDeleteMarker(String key, String markerId) {
        List<ObjectVersion> versions = store.getOrDefault(key, List.of());
        versions.removeIf(v -> v.versionId().equals(markerId) && v.deleteMarker());
    }

    String getCurrent(String key) {
        List<ObjectVersion> versions = store.getOrDefault(key, List.of());
        if (versions.isEmpty()) return "NONE";
        ObjectVersion top = versions.get(versions.size() - 1);
        return top.deleteMarker() ? "HIDDEN (delete marker)" : top.data();
    }

    String getVersion(String key, String versionId) {
        return store.getOrDefault(key, List.of()).stream()
                .filter(v -> v.versionId().equals(versionId))
                .map(ObjectVersion::data).findFirst().orElse("NOT-FOUND");
    }

    // Lifecycle rule: permanently expire noncurrent versions older than N days.
    int expireNoncurrentOlderThan(String key, int days, int today) {
        List<ObjectVersion> versions = store.getOrDefault(key, new ArrayList<>());
        if (versions.size() <= 1) return 0;
        List<ObjectVersion> noncurrent = versions.subList(0, versions.size() - 1);
        int before = noncurrent.size();
        noncurrent.removeIf(v -> (today - v.dayCreated()) > days);
        return before - noncurrent.size();
    }
}

// ─── Would be in ObjectVersion.java ───
