class SecurityAuditor {
    private final BucketSecurity security;
    SecurityAuditor(BucketSecurity security) { this.security = security; }

    // Layered checks: public access, principal allow-list, TLS requirement.
    String evaluate(AccessRequest req) {
        if (security.blockPublicAccess() && "anonymous".equals(req.principal())) {
            return "DENIED — Block Public Access overrides any policy";
        }
        if (!security.allowedPrincipals().contains(req.principal())) {
            return "DENIED — principal not in least-privilege allow-list";
        }
        if (security.requireTls() && !req.overTls()) {
            return "DENIED — request not over TLS (aws:SecureTransport=false)";
        }
        return "ALLOWED — GetObject over TLS, data decrypted via KMS";
    }
}

