class SecureApp {
    private final IamRole role;
    private final SecretStore secrets;
    private String cachedPassword;

    SecureApp(IamRole role, SecretStore secrets) {
        this.role = role; this.secrets = secrets;
        this.cachedPassword = secrets.get("prod/nbi-ledger/credentials");
    }

    // Uses the role's temporary credentials; the SDK would do this transparently.
    String readFromS3(String bucket) {
        String creds = role.issueTemporaryCredentials();
        return "GetObject on " + bucket + " authorized by " + creds;
    }

    String currentDbPassword() { return cachedPassword; }

    // On rotation (or auth failure) refresh from Secrets Manager.
    String refreshAndGetDbPassword() {
        this.cachedPassword = secrets.get("prod/nbi-ledger/credentials");
        return cachedPassword;
    }
}

