class IamRole {
    private final String roleName;
    private int tokenSeq = 0;
    IamRole(String roleName) { this.roleName = roleName; }
    // Short-lived credentials that rotate automatically — never static keys.
    String issueTemporaryCredentials() {
        return roleName + "#temp-" + (++tokenSeq) + " (expires ~1h, auto-rotated)";
    }
}

// ─── Would be in SecretStore.java ───
class SecretStore {
    private final java.util.Map<String, String> values = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> versions = new java.util.HashMap<>();

    void put(String id, String value) { values.put(id, value); versions.put(id, 1); }
    String get(String id) { return values.get(id) + " (KMS-encrypted, v" + versions.get(id) + ")"; }
    void rotate(String id, String newValue) {
        values.put(id, newValue);
        versions.merge(id, 1, Integer::sum);
    }
}

