package com.bank.org;

import java.util.*;
import java.util.logging.*;

public class MultiAccountDemo {
    private static final Logger log = Logger.getLogger("MultiAccount");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AwsOrganization org = new AwsOrganization();
        org.addAccount(new AwsAccount("111111111111", "dev"));
        org.addAccount(new AwsAccount("222222222222", "staging"));
        org.addAccount(new AwsAccount("333333333333", "prod"));
        // SCP guardrail: no account may disable audit logging.
        org.applyServiceControlPolicy("cloudtrail:StopLogging");

        // Blast radius isolation: a dev action cannot reach prod.
        log.info(() -> "Dev deleting a prod resource: "
                + org.canActAcross("111111111111", "333333333333"));

        // SCP blocks a forbidden action even for an account admin.
        log.severe(() -> "Prod admin StopLogging: " + org.attemptAction("333333333333", "cloudtrail:StopLogging"));
        log.info(() -> "Prod admin create S3 bucket: " + org.attemptAction("333333333333", "s3:CreateBucket"));

        // Consolidated billing across the organization.
        log.info(() -> "Consolidated bill covers accounts: " + org.accountIds());

        // SSO: a developer can reach dev/staging, not prod.
        SsoAccess sso = new SsoAccess(Map.of(
                "rajesh.kumar", Set.of("111111111111", "222222222222")));
        log.info(() -> "Rajesh -> dev: " + sso.canAccess("rajesh.kumar", "111111111111"));
        log.warning(() -> "Rajesh -> prod: " + sso.canAccess("rajesh.kumar", "333333333333"));
    }
}

// ─── Would be in AwsOrganization.java ───
class AwsOrganization {
    private final Map<String, AwsAccount> accounts = new LinkedHashMap<>();
    private final Set<String> deniedActions = new HashSet<>();

    void addAccount(AwsAccount a) { accounts.put(a.id(), a); }
    void applyServiceControlPolicy(String deniedAction) { deniedActions.add(deniedAction); }
    List<String> accountIds() { return new ArrayList<>(accounts.keySet()); }

    // Account boundary: an action in one account cannot affect another.
    String canActAcross(String sourceAccount, String targetAccount) {
        return sourceAccount.equals(targetAccount)
                ? "ALLOWED (same account)"
                : "DENIED — account boundary isolates blast radius (no cross-account reach)";
    }

    // SCP guardrail overrides even account-local admin permissions.
    String attemptAction(String accountId, String action) {
        if (deniedActions.contains(action)) {
            return "DENIED by Service Control Policy (org-wide guardrail, admin cannot override)";
        }
        return "ALLOWED (within account permissions)";
    }
}

// ─── Would be in SsoAccess.java ───
class SsoAccess {
    private final Map<String, Set<String>> userToAccounts;
    SsoAccess(Map<String, Set<String>> userToAccounts) { this.userToAccounts = userToAccounts; }
    String canAccess(String user, String accountId) {
        return userToAccounts.getOrDefault(user, Set.of()).contains(accountId)
                ? "ALLOWED (SSO permission set)"
                : "DENIED (no SSO assignment to this account)";
    }
}

